find:
try:
    d = subprocess.run(["bash", spath], capture_output=True, text=True, timeout=120)
finally:
    os.unlink(spath)
lap.event("deploy", rc=d.returncode, tail=(d.stdout + d.stderr)[-300:])
if d.returncode != 0:
    return finish(lap, "failure", gate="deploy", error=(d.stdout + d.stderr)[-2000:])

replace:
try:
    try:
        d = subprocess.run(["bash", spath], capture_output=True, text=True, timeout=120)
    except subprocess.TimeoutExpired as e:
        out = e.stdout or ""
        err = e.stderr or ""
        if isinstance(out, bytes):
            out = out.decode("utf-8", "replace")
        if isinstance(err, bytes):
            err = err.decode("utf-8", "replace")
        lap.event("deploy", rc="timeout", timed_out=True,
                  timeout=e.timeout, tail=(out + err)[-300:])
        return finish(lap, "failure", gate="deploy-timeout",
                      error="%s: %s" % (type(e).__name__, e))
finally:
    os.unlink(spath)
lap.event("deploy", rc=d.returncode, tail=(d.stdout + d.stderr)[-300:])
if d.returncode != 0:
    return finish(lap, "failure", gate="deploy", error=(d.stdout + d.stderr)[-2000:])
